return out(p(`<b>Itinerary</b> for ${esc(t.name)}`)+`<ul class="icc-days">${days}</ul>`+`<p class="icc-note"><a href="${esc(pkgUrl(t))}#itinerary">Full day-by-day itinerary</a></p>`+actions(t),pkgChips(t).filter(c=>c.intent!=='itin'),[t.id]);
